package com.toir.service.repair;

import com.toir.dto.repaircampaign.*;
import com.toir.entity.*;
import com.toir.entity.repair.*;
import com.toir.entity.users.*;
import com.toir.enums.*;
import com.toir.exception.RestException;
import com.toir.repository.*;
import com.toir.repository.projects.*;
import com.toir.repository.repair.*;
import com.toir.repository.users.*;
import com.toir.security.ScopeAccessService;
import com.toir.util.AuditBuilderService;
import lombok.RequiredArgsConstructor;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;

@Service @RequiredArgsConstructor
public class RepairCampaignResourcePolicy {
 private final RepairCampaignRepository campaigns; private final RepairCampaignDepartmentRepository campaignDepartments;
 private final RepairCampaignWorkItemRepository items; private final RepairCampaignResourceAssignmentRepository assignments;
 private final EmployeeRepository employees; private final BrigadeRepository brigades; private final CounteragentRepository counteragents;
 private final BrigadeMemberRepository brigadeMembers; private final UserCertificationRepository certifications;
 private final CertificationTypeRepository certificationTypes; private final ScopeAccessService scope; private final AuditBuilderService audit;

 @Transactional(readOnly=true) public List<RepairCampaignResourceResponse> list(UUID id){var c=find(id,false);return rows(id).stream().map(a->response(a,c.getVersion(),true)).toList();}
 @Transactional public RepairCampaignResourceResponse add(UUID id,RepairCampaignResourceRequest r){var c=find(id,true);version(c,r.version());mutable(c);items.findByIdAndCampaignIdAndIsDeletedFalse(r.workItemId(),id).orElseThrow(()->RestException.badRequest("RESOURCE_FOREIGN_ITEM"));validateRequest(r);validateLockedResource(c,r);var conflicts=assignments.findActiveOverlaps(r.employeeId(),r.brigadeId(),r.counteragentId(),r.plannedStartAt(),r.plannedEndAt(),null);if(conflicts!=null&&!conflicts.isEmpty())throw RestException.conflict("RESOURCE_CONFLICT");var a=new RepairCampaignResourceAssignment();a.setRepairCampaignId(id);a.setWorkItemId(r.workItemId());a.setEmployeeId(r.employeeId());a.setBrigadeId(r.brigadeId());a.setCounteragentId(r.counteragentId());a.setShiftCode(r.shiftCode().trim());a.setPlannedStartAt(r.plannedStartAt());a.setPlannedEndAt(r.plannedEndAt());a.setCompetencyRequirement(norm(r.competencyRequirement()));try{assignments.saveAndFlush(a);}catch(DataIntegrityViolationException e){if(messages(e).contains("uq_repair_campaign_resources_active_identity"))throw RestException.conflict("RESOURCE_CONFLICT");throw e;}var out=response(a,touch(c),true);audit.log("repair_campaign_resource",a.getId().toString(),AuditAction.CREATE,AuditModule.REPAIR_CAMPAIGN,"Resource assigned",null,out);return out;}
 @Transactional public RepairCampaignResourceResponse remove(UUID c,UUID id,Long v){var campaign=find(c,true);version(campaign,v);mutable(campaign);var a=assignments.findByIdAndRepairCampaignIdAndIsDeletedFalse(id,c).orElseThrow(()->RestException.notFound("Resource assignment not found"));lockResource(a);var before=response(a,campaign.getVersion(),true);a.setDeleted(true);assignments.saveAndFlush(a);var out=response(a,touch(campaign),false);audit.log("repair_campaign_resource",id.toString(),AuditAction.DELETE,AuditModule.REPAIR_CAMPAIGN,"Resource removed",before,out);return out;}
 @Transactional(readOnly=true) public List<String> blockers(UUID campaignId){var resources=rows(campaignId);List<String>b=new ArrayList<>();Set<UUID>assigned=new HashSet<>();resources.forEach(a->assigned.add(a.getWorkItemId()));items.findAllByCampaignIdAndIsDeletedFalseOrderByOrderNumberAsc(campaignId).stream().filter(i->i.getPriority()==RepairCampaignPriority.CRITICAL&&!assigned.contains(i.getId())).forEach(i->b.add("CRITICAL_WORK_UNASSIGNED:"+i.getId()));for(var a:resources){if(!active(a)){b.add("RESOURCE_INACTIVE:"+a.getId());continue;}if(!competent(a,a.getCompetencyRequirement()))b.add("COMPETENCY_MISSING:"+a.getId());var overlaps=assignments.findActiveOverlaps(a.getEmployeeId(),a.getBrigadeId(),a.getCounteragentId(),a.getPlannedStartAt(),a.getPlannedEndAt(),a.getId());if(overlaps!=null)for(var x:overlaps)if(a.getId().compareTo(x.getId())<0)b.add("RESOURCE_CONFLICT:"+a.getId()+":"+x.getId());}return b.stream().distinct().sorted().toList();}
 public boolean assigned(UUID c,UUID i){return assignments.existsByRepairCampaignIdAndWorkItemIdAndIsDeletedFalse(c,i);}
 private void validateRequest(RepairCampaignResourceRequest r){if(r==null||r.shiftCode()==null||r.shiftCode().isBlank()||r.plannedStartAt()==null||r.plannedEndAt()==null||!r.plannedEndAt().isAfter(r.plannedStartAt()))throw RestException.badRequest("RESOURCE_WINDOW_INVALID");if((r.employeeId()!=null?1:0)+(r.brigadeId()!=null?1:0)+(r.counteragentId()!=null?1:0)!=1)throw RestException.badRequest("RESOURCE_EXACTLY_ONE_REQUIRED");}
 private void validateLockedResource(RepairCampaign c,RepairCampaignResourceRequest r){Object resource;if(r.employeeId()!=null)resource=employees.findByIdAndIsDeletedFalseForUpdate(r.employeeId()).filter(Employee::isActive).orElseThrow(()->RestException.badRequest("RESOURCE_INACTIVE"));else if(r.brigadeId()!=null)resource=brigades.findByIdAndIsDeletedFalseForUpdate(r.brigadeId()).filter(Brigade::isActive).orElseThrow(()->RestException.badRequest("RESOURCE_INACTIVE"));else resource=counteragents.findByIdAndIsDeletedFalseForUpdate(r.counteragentId()).filter(x->x.getStatus()==CounteragentStatus.ACTIVE).orElseThrow(()->RestException.badRequest("RESOURCE_INACTIVE"));UUID dept=resource instanceof Employee e?e.getDepartmentId():resource instanceof Brigade b?b.getDepartmentId():null;if(dept!=null){scope.assertCanAccessDepartment(dept);if(!allowedDepartments(c).contains(dept))throw new AccessDeniedException("RESOURCE_SCOPE_FORBIDDEN");}if(!competent(resource,norm(r.competencyRequirement())))throw RestException.badRequest("COMPETENCY_MISSING");}
 private Set<UUID> allowedDepartments(RepairCampaign c){Set<UUID>s=new HashSet<>();if(c.getDepartmentId()!=null)s.add(c.getDepartmentId());campaignDepartments.findAllByCampaignIdAndIsDeletedFalse(c.getId()).forEach(x->s.add(x.getDepartmentId()));return s;}
 private boolean active(RepairCampaignResourceAssignment a){if(a.getEmployeeId()!=null)return employees.findByIdAndIsDeletedFalse(a.getEmployeeId()).filter(Employee::isActive).isPresent();if(a.getBrigadeId()!=null)return brigades.findByIdAndIsDeletedFalse(a.getBrigadeId()).filter(Brigade::isActive).isPresent();return counteragents.findByIdAndIsDeletedFalse(a.getCounteragentId()).filter(x->x.getStatus()==CounteragentStatus.ACTIVE).isPresent();}
 private boolean competent(RepairCampaignResourceAssignment a,String need){Object r=a.getEmployeeId()!=null?employees.findByIdAndIsDeletedFalse(a.getEmployeeId()).orElse(null):a.getBrigadeId()!=null?brigades.findByIdAndIsDeletedFalse(a.getBrigadeId()).orElse(null):counteragents.findByIdAndIsDeletedFalse(a.getCounteragentId()).orElse(null);return competent(r,need);}
 private boolean competent(Object r,String need){String required=normSkill(need);if(required==null)return true;if(r instanceof Employee e)return values(required,e.getPosition(),e.getGrade(),e.getSpecialisationId()==null?null:e.getSpecialisationId().toString())||certified(e.getUserId(),required);if(r instanceof Brigade b){if(values(required,b.getSpecialization()))return true;return brigadeMembers.findAllByBrigadeIdAndIsDeletedFalse(b.getId()).stream().filter(BrigadeMember::isActive).anyMatch(m->(m.getQualifications()!=null&&m.getQualifications().stream().map(this::normSkill).anyMatch(required::equals))||certified(m.getUserId(),required));}return false;}
 private boolean certified(UUID user,String need){if(user==null)return false;return certifications.findAllByUserIdAndIsDeletedFalse(user).stream().anyMatch(c->"ACTIVE".equalsIgnoreCase(c.getStatus())&&(c.getExpiresAt()==null||!c.getExpiresAt().isBefore(LocalDate.now()))&&certMatches(c,need));}
 private boolean certMatches(UserCertification c,String n){if(n.equals(normSkill(c.getTypeCode())))return true;CertificationType t=c.getTypeCode()==null?null:certificationTypes.findByCodeAndIsDeletedFalse(c.getTypeCode());return t!=null&&values(n,t.getCode(),t.getName(),t.getNameEn(),t.getNameUz());}
 private boolean values(String n,Object...v){return Arrays.stream(v).filter(Objects::nonNull).map(Object::toString).map(this::normSkill).anyMatch(n::equals);}private String normSkill(String s){return s==null||s.isBlank()?null:s.trim().toLowerCase(Locale.ROOT).replaceAll("[\\s_\\-]+","");}private static String norm(String s){return s==null||s.isBlank()?null:s.trim();}
 private void lockResource(RepairCampaignResourceAssignment a){if(a.getEmployeeId()!=null)employees.findByIdAndIsDeletedFalseForUpdate(a.getEmployeeId());else if(a.getBrigadeId()!=null)brigades.findByIdAndIsDeletedFalseForUpdate(a.getBrigadeId());else counteragents.findByIdAndIsDeletedFalseForUpdate(a.getCounteragentId());}
 private RepairCampaign find(UUID id,boolean lock){var c=(lock?campaigns.findLockedByIdAndIsDeletedFalse(id):campaigns.findByIdAndIsDeletedFalse(id)).orElseThrow(()->RestException.notFound("Campaign not found"));scope.assertCanAccessDepartment(c.getDepartmentId());return c;}private static void version(RepairCampaign c,Long v){if(v==null||!Objects.equals(v,c.getVersion()))throw RestException.conflict("CAMPAIGN_VERSION_CONFLICT");}private static void mutable(RepairCampaign c){if(c.getStatus()==RepairCampaignStatus.PENDING_APPROVAL)throw RestException.conflict("CAMPAIGN_PLANNING_APPROVAL_INVALIDATION_REQUIRED");if(c.getStatus().ordinal()>=RepairCampaignStatus.APPROVED.ordinal())throw RestException.conflict("CAMPAIGN_PLANNING_FROZEN");}private long touch(RepairCampaign c){c.setUpdatedAt(Instant.now());return campaigns.saveAndFlush(c).getVersion();}private List<RepairCampaignResourceAssignment> rows(UUID id){return assignments.findAllByRepairCampaignIdAndIsDeletedFalseOrderByPlannedStartAtAscIdAsc(id);}private static String messages(Throwable e){StringBuilder s=new StringBuilder();for(Throwable x=e;x!=null;x=x.getCause())s.append(' ').append(x.getMessage());return s.toString();}private static RepairCampaignResourceResponse response(RepairCampaignResourceAssignment a,long v,boolean active){return new RepairCampaignResourceResponse(a.getId(),a.getRepairCampaignId(),a.getWorkItemId(),a.getEmployeeId(),a.getBrigadeId(),a.getCounteragentId(),a.getShiftCode(),a.getPlannedStartAt(),a.getPlannedEndAt(),a.getCompetencyRequirement(),v,active);}
}
